-- Pengingat Little Chef: tambahkan link cek pendaftaran.
update public.sessions set reminders = '[{"id": "bayar", "name": "Pengingat pembayaran", "email_subject": "Pengingat pembayaran {{judul}} ({{kode}})", "text": "Halo Bapak/Ibu, kami dari Sparks English Klampis 😊\n\nMengingatkan pembayaran {{judul}} untuk {{nama_siswa}} ({{jadwal}}).\n\nKode pendaftaran: {{kode}}\nTotal: {{total}}\n\nTransfer ke {{bank}} {{no_rekening}} a.n. {{atas_nama}}, lalu kirim bukti transfer ke Student Advisor ({{student_advisor}}).\n\nCek pendaftaran & rincian pembayaran:\n{{link_cek}}\n\nTerima kasih!"}, {"id": "hadir", "name": "Pengingat kehadiran", "email_subject": "Sampai jumpa di {{judul}}!", "text": "Halo Bapak/Ibu, sampai jumpa di {{judul}}! 🍕\n\nSiswa: {{nama_siswa}}\nJadwal: {{jadwal}}\nTanggal: {{tanggal_acara}}\nLokasi: {{lokasi}}\nKode pendaftaran: {{kode}}\n\nDetail pendaftaran:\n{{link_cek}}\n\nMohon datang 15 menit lebih awal ya. *Jika tidak datang saat hari H, uang pendaftaran hangus.\n\nTerima kasih!"}]'::jsonb
where slug = 'little-chefs';
